def edit_distance(s1, s2):
    memo = {}
    def helper(s1, s2):
        if (s1, s2) in memo:
            return memo[(s1, s2)]
        if not s1:
            result = len(s2)
        elif not s2:
            result = len(s1)
        elif s1[0] == s2[0]:
            result = helper(s1[1:], s2[1:])
        else:
            result = 1 + min(helper(s1, s2[1:]), helper(s1[1:], s2))
        memo[(s1, s2)] = result
        return result
    return helper(s1, s2)
